_cuda_src = r'''
extern "C" __global__
void l2_norm_kernel(const half* __restrict__ A,
                    half* __restrict__ O,
                    int dim) {
    // one block per row (batch element)
    int row = blockIdx.x;
    // each thread accumulates a chunk of the row
    float sum = 0.0f;
    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        half hv = A[row * dim + i];
        float fv = __half2float(hv);
        sum += fv * fv;
    }
    // reduction in shared memory
    extern __shared__ float s[];
    s[threadIdx.x] = sum;
    __syncthreads();
    for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
        if (threadIdx.x < offset) {
            s[threadIdx.x] += s[threadIdx.x + offset];
        }
        __syncthreads();
    }
    float inv_norm = rsqrtf(s[0] + 1e-12f);  // 1 / sqrt(sum)

    // write normalized values
    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        half hv = A[row * dim + i];
        float fv = __half2float(hv);
        O[row * dim + i] = __float2half(fv * inv_norm);
    }
}
'''

