#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

void l2_norm_launcher(at::Tensor A, at::Tensor O) {
    TORCH_CHECK(A.is_cuda() && O.is_cuda(), "Tensors must be CUDA");
    TORCH_CHECK(A.dtype() == torch::kHalf && O.dtype() == torch::kHalf,
                "Tensors must be float16");
    TORCH_CHECK(A.sizes().size() == 2, "Input must be 2‑D");
    TORCH_CHECK(A.sizes() == O.sizes(), "Input and output shapes must match");

    int batch = A.size(0);
    int dim   = A.size(1);

    const int threads = 256;
    dim3 grid(batch);
    dim3 block(threads);
    size_t shared_mem = threads * sizeof(float);

    // launch kernel
