class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference L2‑normalization model.
    All tensors are expected to be float16 (fp16).
    """
    def __init__(self):
        super().__init__()
        # The compiled module is stored as a class attribute for reuse.
        self._mod = _l2norm_mod

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if x.dtype != torch.float16:
            raise TypeError("ModelNew expects fp16 (torch.float16) input")
        if not x.is_cuda:
            raise RuntimeError("Input tensor must be on CUDA device")
        # Ensure contiguous layout for pointer arithmetic
        x_contig = x.contiguous()
        out = torch.empty_like(x_contig)
        # Launch the kernel
        self._mod.l2_norm(x_contig, out)
        return out

